    pricing_faq_title: "Common Questions",
    pricing_faq_q1: "Can I change my plan at any time?",
    pricing_faq_a1: "Yes. Upgrades take effect immediately. Downgrades take effect at the start of your next billing cycle. No lock-in periods on monthly plans.",
    pricing_faq_q2: "Is there a free trial?",
    pricing_faq_a2: "We offer a 14-day trial for Starter and Professional plans. Request it through the contact form — we'll set up a live environment with your business data.",
