    pricing_faq_a3: "Any task executed by an AI Employee: sending an email, responding to a message, booking an appointment, generating a report, or completing a workflow step.",
    pricing_faq_q4: "Are integrations included or extra cost?",
    pricing_faq_a4: "Starter includes 1 integration. Professional includes unlimited integrations. All standard connectors (WhatsApp, Gmail, Outlook, Google Calendar) are included at no extra cost.",
