    legalpriv_label: "Legal",
    legalpriv_title: "Privacy Policy",
    legalpriv_desc: "This Privacy Policy explains how THE BLUE BRIDGE CONNECTION CO SOCIEDAD DE RESPONSABILIDAD LIMITADA, trading as Blue Bridge Global Connection, collects, uses, and protects personal data.",
    legalpriv_s1_heading: "1. Who We Are",
    legalpriv_s1_intro: "The data controller responsible for your personal information is:",
    legalpriv_s1_identity_details: "Trading as: <strong>Blue Bridge Global Connection</strong><br>Registration No.: 3-102-880-591<br>Registered Office: Alpha Legal, Boulevard Dent, Barrio Dent, San Pedro, Montes de Oca, San José 11501, Costa Rica<br>Email: <a href=\"mailto:privacy@bluebridge.es\" style=\"color:var(--blue);\">privacy@bluebridge.es</a>",
    legalpriv_s2_heading: "2. Data We Collect",
    legalpriv_s2_intro: "We collect information you provide directly and data collected automatically when you use our services:",
    legalpriv_s2_1_heading: "2.1 Information You Provide",
    legalpriv_s2_li_contact: "Contact details: name, email address, phone number, company name",
    legalpriv_s2_li_account: "Account information: username, password (hashed), preferences",
    legalpriv_s2_li_business: "Business information: company type, industry, company size",
    legalpriv_s2_li_communications: "Communications: messages sent through our contact forms or support channels",
    legalpriv_s2_li_payment: "Payment information: processed by our payment processors (we do not store card details)",
    legalpriv_s2_2_heading: "2.2 Data Collected Automatically",
    legalpriv_s2_li_usage: "Usage data: pages visited, features used, time spent, clickstream data",
    legalpriv_s2_li_technical: "Technical data: IP address, browser type, device type, operating system",
    legalpriv_s2_li_cookies: "Cookies and similar tracking technologies (see our <a href=\"cookies.html\" style=\"color:var(--blue);\">Cookie Policy</a>)",
    legalpriv_s3_heading: "3. Legal Basis for Processing",
    legalpriv_s3_intro: "Under GDPR Article 6, we process your data based on the following legal grounds:",
    legalpriv_s3_basis_contract_label: "Contractual necessity (Art. 6.1.b):",
    legalpriv_s3_basis_contract_desc: "To provide our services and fulfill our contractual obligations to you.",
    legalpriv_s3_basis_legitimate_label: "Legitimate interests (Art. 6.1.f):",
    legalpriv_s3_basis_legitimate_desc: "To improve our services, prevent fraud, and ensure security.",
    legalpriv_s3_basis_consent_label: "Consent (Art. 6.1.a):",
    legalpriv_s3_basis_consent_desc: "For marketing communications and non-essential cookies (where explicitly obtained).",
    legalpriv_s3_basis_legal_label: "Legal obligation (Art. 6.1.c):",
    legalpriv_s3_basis_legal_desc: "To comply with applicable laws and regulatory requirements.",
    legalpriv_s4_heading: "4. How We Use Your Data",
    legalpriv_s4_li_provide: "To provide and manage our AI services and platforms",
    legalpriv_s4_li_payments: "To process payments and manage subscriptions",
    legalpriv_s4_li_communicate: "To communicate with you regarding your account and our services",
    legalpriv_s4_li_notifications: "To send service notifications and (with consent) marketing communications",
    legalpriv_s4_li_analyze: "To analyze and improve our products and services",
    legalpriv_s4_li_fraud: "To detect and prevent fraud, abuse, and security incidents",
    legalpriv_s4_li_compliance: "To comply with legal obligations and regulatory requirements",
    legalpriv_s5_heading: "5. Data Sharing & Sub-Processors",
    legalpriv_s5_intro: "We do not sell, rent, or trade personal data. We share data only with trusted sub-processors necessary for service delivery, under appropriate data protection agreements:",
