    legalcookies_label: "Legal",
    legalcookies_title: "Cookie Policy",
    legalcookies_intro: "This Cookie Policy explains how Blue Bridge Global Connection uses cookies and similar technologies on our website and platforms.",
    legalcookies_h2_what_are_cookies: "1. What Are Cookies?",
    legalcookies_what_are_cookies_body: "Cookies are small text files placed on your device when you visit a website. They help websites remember your preferences, keep you logged in, and understand how visitors use the site. Similar technologies include web beacons, pixels, and local storage.",
    legalcookies_h2_categories: "2. Cookie Categories",
    legalcookies_cat_necessary_title: "Strictly Necessary Cookies",
    legalcookies_badge_always_active: "Always Active",
    legalcookies_cat_necessary_desc: "These cookies are essential for the website to function and cannot be disabled. They are usually set in response to actions you take, such as logging in or filling in forms.",
    legalcookies_th_cookie: "Cookie",
    legalcookies_th_purpose: "Purpose",
    legalcookies_th_duration: "Duration",
    legalcookies_purpose_auth_session: "User authentication session",
    legalcookies_duration_session: "Session",
    legalcookies_purpose_csrf: "Security token (CSRF protection)",
    legalcookies_purpose_consent_pref: "Cookie consent preference",
    legalcookies_duration_12months: "12 months",
    legalcookies_purpose_lang_pref: "Language preference",
    legalcookies_cat_analytics_title: "Performance & Analytics Cookies",
    legalcookies_badge_consent_required: "Consent Required",
    legalcookies_cat_analytics_desc: "These cookies help us understand how visitors use our website by collecting anonymous statistical information.",
    legalcookies_th_provider: "Provider",
    legalcookies_purpose_user_id_anon: "User identification (anonymized)",
    legalcookies_duration_2years: "2 years",
    legalcookies_purpose_session_tracking: "Session tracking",
    legalcookies_purpose_session_diff: "Session differentiation",
    legalcookies_duration_24hours: "24 hours",
    legalcookies_cat_functional_title: "Functional Cookies",
    legalcookies_cat_functional_desc: "These cookies enable enhanced functionality and personalization.",
    legalcookies_purpose_theme_pref: "UI theme preference (dark/light)",
    legalcookies_purpose_last_conv: "Last conversation state (client portal)",
    legalcookies_cat_marketing_title: "Marketing Cookies",
    legalcookies_cat_marketing_desc: "We currently do not use marketing or advertising cookies. If we introduce them in the future, we will update this policy and request your consent.",
    legalcookies_h2_managing: "3. Managing Your Cookies",
    legalcookies_managing_intro: "You have several options to control cookie usage:",
    legalcookies_manage_banner: "<strong>Cookie banner:</strong> When you first visit our site, you can choose to accept or decline non-essential cookies",
    legalcookies_manage_browser: "<strong>Browser settings:</strong> Most browsers allow you to refuse or delete cookies through their settings",
    legalcookies_manage_ga_optout: "<strong>Google Analytics opt-out:</strong> Install the Google Analytics browser add-on to prevent data collection",
    legalcookies_manage_contact: "<strong>Contact us:</strong> Email privacy@bluebridge.es to reset your consent or request data deletion",
    legalcookies_note_label: "Note:",
    legalcookies_note_text: "Disabling strictly necessary cookies will impact website functionality and may prevent you from logging into your account.",
    legalcookies_h2_third_party: "4. Third-Party Cookies",
    legalcookies_third_party_body: "Some cookies on our site are set by third-party services. These third parties have their own privacy policies which we encourage you to review: <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--blue);\">Google Privacy Policy</a>.",
    legalcookies_h2_updates: "5. Updates to This Policy",
    legalcookies_updates_body: "We may update this Cookie Policy when we change our cookie usage or in response to changes in privacy regulations. The date at the top of this page indicates when it was last updated.",
    legalcookies_questions_title: "Questions?",
    legalcookies_questions_body: "Contact our privacy team at <a href=\"mailto:privacy@bluebridge.es\" style=\"color:var(--blue);\">privacy@bluebridge.es</a> or visit our <a href=\"privacy-policy.html\" style=\"color:var(--blue);\">Privacy Policy</a> for more information on how we handle your personal data.",
    legalcookies_reset_button: "Reset My Cookie Preferences",
    legalsec_breadcrumb_home: "Home",
    legalsec_breadcrumb_legal: "Legal",
    legalsec_breadcrumb_current: "Security",
    legalsec_label_hero: "Security",
    legalsec_title: "Security Overview",
    legalsec_intro: "A transparent description of the technical and organizational security measures protecting Blue Bridge systems, client data, and service integrity.",
    legalsec_label_infrastructure: "Infrastructure",
    legalsec_infra_title: "Cloud Infrastructure",
    legalsec_infra_desc: "All Blue Bridge production systems run on BB Cloud — our enterprise-grade cloud platform built for reliability at scale.",
    legalsec_card_multiregion_title: "Multi-Region",
    legalsec_card_multiregion_desc: "Primary: North America (Virginia). EMEA: Europe (Ireland). Cross-region replication for critical data.",
    legalsec_card_cdn_title: "Global CDN",
    legalsec_card_cdn_desc: "Global content delivery via our CDN with 400+ edge locations worldwide. DDoS protection included.",
    legalsec_card_vpc_title: "Private VPC",
    legalsec_card_vpc_desc: "All compute resources run inside a private Virtual Private Cloud. No direct public internet access to backend systems.",
    legalsec_card_waf_title: "WAF Protection",
    legalsec_card_waf_desc: "Our web application firewall protects against OWASP Top 10, SQL injection, XSS, and bot attacks.",
    legalsec_card_autoscaling_title: "Auto Scaling",
    legalsec_card_autoscaling_desc: "Elastic infrastructure automatically scales to handle traffic spikes without service degradation.",
    legalsec_card_iam_title: "IAM Policies",
    legalsec_card_iam_desc: "Identity and Access Management with fine-grained permissions. No wildcard IAM policies in production.",
    legalsec_label_encryption: "Encryption",
    legalsec_h2_encryption: "Encrypted Communications",
    legalsec_h3_data_at_rest: "Data at Rest",
    legalsec_encrypt_rest_aes256: "AES-256 encryption for all stored data (databases, files, backups)",
    legalsec_encrypt_rest_kms: "Managed Key Management Service (KMS) for encryption key management",
    legalsec_encrypt_rest_postgres: "Managed PostgreSQL with encryption enabled at the storage level",
    legalsec_encrypt_rest_objectstorage: "Server-side encryption for all object storage",
    legalsec_encrypt_rest_redis: "Encrypted Redis for session and cache data",
    legalsec_h3_data_in_transit: "Data in Transit",
    legalsec_transit_tls: "TLS 1.3 enforced for all HTTP connections (HTTPS everywhere)",
