    solhub_ai_workforce_desc: "Despliegue equipos de agentes de IA autónomos que trabajan las 24 horas del día en toda su operación. Cada agente se especializa en un dominio y colabora con los demás mediante flujos de trabajo orquestados.",
    solhub_ai_agents_desc: "Agentes inteligentes personalizados, entrenados con el contexto de su negocio. Integrados con sus sistemas existentes mediante API. Desplegados en su infraestructura o gestionados por nosotros.",
    solhub_support_desc: "Agentes de IA de soporte que resuelven las consultas de los clientes al instante en todos los canales. Gestionan soporte de nivel 1 y nivel 2, escalando a agentes humanos solo cuando es necesario.",
    solhub_voice_desc: "Agentes telefónicos inteligentes impulsados por Twilio. Gestionan llamadas entrantes, dirigen consultas, toman reservas y resuelven incidencias con una conversación natural y humana.",
    solhub_booking_desc: "Plataformas completas de gestión de reservas y citas. Programación impulsada por IA, recordatorios automatizados, procesamiento de pagos e integración con CRM.",
    solhub_crm_desc: "Sistemas CRM empresariales creados para su sector. Puntuación de leads impulsada por IA, gestión del pipeline, seguimiento automatizado y análisis de ingresos.",
    solhub_automation_desc: "Automatización integral de procesos empresariales, de principio a fin. Conecte sus herramientas, fuentes de datos y equipos en flujos de trabajo inteligentes que se ejecutan automáticamente.",
    solhub_software_desc: "Software empresarial a medida, construido con arquitectura moderna cloud-native. Backends en FastAPI, frontends en Next.js, bases de datos PostgreSQL y despliegue con Docker.",
    solhub_web_desc: "Sitios web y aplicaciones web empresariales. Con prioridad en el rendimiento, optimizados para SEO, accesibles según WCAG y diseñados para convertir visitantes en clientes.",
    solhub_cloud_desc: "Diseño, despliegue y gestión de infraestructura en BB Cloud. Arquitectura en la nube segura, escalable y optimizada en costes para cargas de trabajo empresariales de cualquier escala.",
