    about_value_transparency_desc: "Somos transparentes sobre nuestra tecnología, nuestros procesos y nuestras limitaciones. Sin cajas negras, sin costos ocultos.",
    about_value_security_title: "Seguridad Primero",
    about_value_security_desc: "La seguridad de nivel empresarial no es opcional. Cada sistema que construimos se diseña con la seguridad como principio fundamental.",
    about_value_partnership_title: "Colaboración",
    about_value_partnership_desc: "Tenemos éxito cuando nuestros clientes tienen éxito. Relaciones de largo plazo basadas en confianza, responsabilidad y resultados.",
    about_value_excellence_title: "Excelencia",
    about_value_excellence_desc: "Establecemos altos estándares en calidad de código, diseño, rendimiento y comunicación con el cliente.",
    about_value_responsible_title: "IA Responsable",
    about_value_responsible_desc: "IA que beneficia a la humanidad. Rechazamos activamente aplicaciones que dañen a las personas, discriminen o invadan la privacidad.",
    about_value_local_title: "Comprensión Local",
    about_value_local_desc: "Tecnología global con conocimiento del mercado local. Comprendemos la cultura empresarial, la normativa y el idioma de cada mercado al que servimos.",
    about_cta_label: "Trabaje con Nosotros",
    about_cta_team_btn: "Conozca a Nuestro Equipo",
    solva_hero_desc: "Transforme su canal telefónico con Empleados IA que responden llamadas las 24 horas, los 7 días de la semana, hablan con naturalidad, comprenden el contexto y completan tareas — desde agendar citas hasta resolver casos de soporte.",
    solva_hero_cta: "Implementar IA de Voz",
    solva_features_label: "Funciones",
    solva_features_title: "Qué Incluye",
    solva_feature_natural_title: "Conversación Natural",
    solva_feature_natural_desc: "IA de voz avanzada que comprende el contexto, gestiona interrupciones y responde con naturalidad — nada que ver con un IVR robótico.",
    solva_feature_twilio_title: "Impulsado por Twilio",
