    solba_hero_desc: "Una plataforma completa de reservas y gestión de citas con IA en su núcleo. Sus clientes pueden reservar las 24 horas, los 7 días de la semana, por web, WhatsApp, teléfono o cualquier canal — sin intervención humana.",
