    solba_features_title: "Qué Incluye",
    solba_feature_scheduling_title: "Programación Inteligente",
    solba_feature_scheduling_desc: "La IA considera la disponibilidad, la duración del servicio, las limitaciones de recursos y las preferencias para sugerir los horarios óptimos.",
    solba_feature_reminders_title: "Recordatorios Automatizados",
