    solba_feature_multilocation_title: "Multi-Sede",
    solba_feature_multilocation_desc: "Una única plataforma que gestiona reservas en múltiples sedes, miembros del personal y tipos de servicio.",
    solba_feature_calendar_title: "Sincronización de Calendario",
    solba_feature_calendar_desc: "Sincronización bidireccional con Google Calendar, Outlook y Apple Calendar. Nunca más reservas duplicadas.",
    solba_feature_analytics_title: "Analítica",
