    beapartner_why_card1_desc: "Usted opera como un negocio independiente — gestiona su propio tiempo, sus propias obligaciones fiscales y su propia actividad comercial. No hay salario, ni horario fijo, ni relación laboral con Blue Bridge; sus ingresos dependen enteramente de los resultados comerciales.",
    beapartner_why_card2_title: "Su Propiedad Intelectual Es Suya, la Nuestra Es Nuestra",
