    cases_label_challenge: "Desafío",
    cases_label_solution: "Solución",
    cases_1_challenge: "Los pacientes internacionales no podían reservar citas fuera del horario habitual. Las líneas telefónicas estaban saturadas. El 60% de las consultas quedaban sin respuesta.",
    cases_1_solution: "Plataforma de reservas impulsada por IA + agente de Voice AI en inglés y español, integrada con el sistema EHR de la clínica.",
    cases_2_challenge: "Reservas de citas manuales, tasa de inasistencia del 35%, sin programa de fidelización de clientes y gestión de inventario en papel.",
    cases_2_solution: "Implementación completa de SalonOS: reservas digitales, recordatorios automáticos por SMS, programa de fidelización, POS y la asistente de IA Lisa.",
    cases_3_challenge: "El equipo de ingeniería dedicaba el 40% de su tiempo a tickets de soporte interno. Sin sistema de documentación. Incorporación lenta de nuevas contrataciones.",
    cases_3_solution: "AI Workforce a medida: 5 agentes especializados para soporte de TI, documentación, consultas de RR. HH. y gestión de proyectos.",
    cases_4_challenge: "El equipo de atención al cliente estaba saturado en Instagram y WhatsApp. Un tiempo de respuesta promedio de 8 horas hacía perder ventas frente a la competencia.",
    cases_4_solution: "Agentes de soporte con IA desplegados en Instagram DM, WhatsApp y el sitio web. Entrenados con el catálogo completo de productos y las políticas de devolución.",
    cases_5_challenge: "Sistemas de reservas desconectados, programación de personal manual, sin datos de clientes y servicio inconsistente entre locales.",
