    partners_hero_desc: "Colaboramos con las principales empresas tecnológicas del mundo para ofrecer soluciones de IA empresarial de primer nivel.",
    partners_tech_label: "Socios Tecnológicos",
    partners_tech_title: "Impulsado por Líderes de la Industria",
    partners_card1_desc: "Socio principal de infraestructura en la nube. Todos los sistemas de Blue Bridge se ejecutan en BB Cloud con disponibilidad global y seguridad de nivel empresarial.",
    partners_card2_desc: "Socio principal de IA. Nuestros agentes de IA funcionan con Claude, la IA Constitucional de Anthropic diseñada para ser segura, confiable y beneficiosa.",
    partners_card3_desc: "Socio de Voice AI y comunicaciones. Twilio impulsa nuestras capacidades de agentes telefónicos, SMS, WhatsApp Business y mensajería omnicanal.",
    partners_card4_desc: "Socio oficial de Meta Business que permite a nuestros clientes desplegar agentes de IA en Instagram, WhatsApp Business y Facebook Messenger.",
    partners_card5_desc: "Socio de Google Cloud para identidad (Google OAuth), IA documental e integraciones de workspace para clientes empresariales.",
    partners_card6_desc: "Socio de CDN, DNS y seguridad. Cloudflare protege todas las propiedades web de Blue Bridge y de nuestros clientes frente a ataques DDoS, bots y ataques web.",
    partners_card7_desc: "Socio global de procesamiento de pagos para la facturación por suscripción y los pagos únicos en nuestra plataforma para desarrolladores.",
    partners_card8_desc: "Socio de Microsoft 365 y Azure para integraciones de productividad empresarial, y conectividad con Outlook, Teams y SharePoint.",
    partners_card9_desc: "Socio secundario de modelos de IA para casos de uso específicos que requieren GPT-4 y modelos especializados para embeddings y procesamiento de documentos.",
