    partners_type_tech_desc: "Para empresas de software que desean integrar las capacidades de IA de Blue Bridge en sus productos.",
    solwf_page_title: "AI Workforce",
    solwf_hero_desc: "Blue Bridge AI Workforce es una plataforma de más de 24 agentes de IA autónomos especializados que colaboran para gestionar procesos de negocio de principio a fin en toda su organización.",
    solwf_hero_cta: "Implemente su AI Workforce",
    solwf_features_label: "Características",
    solwf_features_title: "Qué Incluye",
    solwf_feature1_title: "Más de 24 Agentes Especializados",
    solwf_feature1_desc: "Cada agente está especializado: infraestructura, ventas, soporte, analítica, recursos humanos, cumplimiento y más. Colaboran mediante flujos de trabajo orquestados.",
    solwf_feature2_title: "Operación 24/7",
    solwf_feature2_desc: "Los agentes de IA trabajan sin descanso, sin vacaciones ni bajas por enfermedad. Sus operaciones continúan sin interrupciones.",
    solwf_feature3_title: "Ejecución Autónoma",
    solwf_feature3_desc: "Los agentes leen registros, escriben código, ejecutan comandos y completan tareas complejas sin supervisión constante.",
    solwf_feature4_title: "Acceso a Herramientas",
    solwf_feature4_desc: "Los agentes tienen acceso a bash, sistemas de archivos, APIs, bases de datos y la web, lo que les permite realizar trabajo real, no solo asesorar.",
