    pricing_addon_actions_desc: "50.000 acciones de IA adicionales al mes para operaciones de alto volumen.",
    pricing_addon_priority_support_title: "Mejora de Soporte Prioritario",
    pricing_addon_priority_support_desc: "Soporte por correo, chat y teléfono con SLA de 2 horas. Disponible en el plan Starter.",
    pricing_faq_label: "FAQ",
    pricing_faq_title: "Preguntas Comunes",
    pricing_faq_q1: "¿Puedo cambiar mi plan en cualquier momento?",
    pricing_faq_a1: "Sí. Las mejoras de plan se aplican de inmediato. Las reducciones de plan se aplican al inicio de su próximo ciclo de facturación. Sin periodos de permanencia en los planes mensuales.",
    pricing_faq_q2: "¿Hay una prueba gratuita?",
    pricing_faq_a2: "Ofrecemos una prueba de 14 días para los planes Starter y Professional. Solicítela a través del formulario de contacto — configuraremos un entorno en vivo con los datos de su negocio.",
    pricing_faq_q3: "¿Qué cuenta como una acción de IA?",
    pricing_faq_a3: "Cualquier tarea ejecutada por un Empleado IA: enviar un correo, responder un mensaje, agendar una cita, generar un informe o completar un paso de un flujo de trabajo.",
    pricing_faq_q4: "¿Las integraciones están incluidas o tienen costo adicional?",
    pricing_faq_a4: "Starter incluye 1 integración. Professional incluye integraciones ilimitadas. Todos los conectores estándar (WhatsApp, Gmail, Outlook, Google Calendar) están incluidos sin costo adicional.",
    pricing_faq_q5: "¿Ofrecen descuentos para organizaciones sin fines de lucro o startups?",
    pricing_faq_a5: "Sí. Descuentos del 25% para organizaciones sin fines de lucro registradas y startups en etapa temprana (con ingresos inferiores a $500,000). Contacte a sales@bluebridge.es con la documentación correspondiente.",
    pricing_faq_q6: "¿Hay una cuota de configuración?",
    pricing_faq_a6: "Sin cuotas de configuración en los planes Starter o Professional. Los planes Enterprise incluyen una cuota de implementación única, cotizada según el alcance, que incluye incorporación completa, integración y pruebas.",
    pricing_faq_cta_text: "¿Aún tiene preguntas? Hable directamente con nuestro equipo.",
    pricing_cta_contact_sales: "Contactar Ventas",
