    blog_featured_badge: "Destacado",
    blog_date_aug2026: "Agosto 2026",
    blog_featured_title: "La Ley de IA de la UE ya está en vigor: lo que los líderes empresariales deben saber",
    blog_featured_excerpt: "La Ley de IA de la UE representa la regulación de IA más completa a nivel mundial. Aquí tienes un desglose práctico para líderes tecnológicos empresariales y los pasos de cumplimiento que toda organización debería tomar ahora.",
    blog_read_article: "Leer artículo",
