    blog_post1_title: "Cómo construir una AI Workforce que realmente funcione: lecciones de 50 implementaciones empresariales",
    blog_post1_excerpt: "Desplegar agentes de IA es fácil. Hacer que sean productivos, confiables y estén alineados con el negocio es la parte difícil. Esto es lo que hemos aprendido.",
