    legalpriv_breadcrumb_current: "Política de Privacidad",
    legalpriv_label: "Legal",
    legalpriv_title: "Política de Privacidad",
    legalpriv_desc: "Esta Política de Privacidad explica cómo THE BLUE BRIDGE CONNECTION CO SOCIEDAD DE RESPONSABILIDAD LIMITADA, que opera bajo el nombre comercial Blue Bridge Global Connection, recopila, utiliza y protege los datos personales.",
    legalpriv_s1_heading: "1. Quiénes Somos",
    legalpriv_s1_intro: "El responsable del tratamiento de sus datos personales es:",
    legalpriv_s1_identity_details: "Nombre comercial: <strong>Blue Bridge Global Connection</strong><br>Número de Registro: 3-102-880-591<br>Domicilio Registrado: Alpha Legal, Boulevard Dent, Barrio Dent, San Pedro, Montes de Oca, San José 11501, Costa Rica<br>Correo electrónico: <a href=\"mailto:privacy@bluebridge.es\" style=\"color:var(--blue);\">privacy@bluebridge.es</a>",
    legalpriv_s2_heading: "2. Datos que Recopilamos",
    legalpriv_s2_intro: "Recopilamos la información que usted nos proporciona directamente y los datos recopilados automáticamente cuando utiliza nuestros servicios:",
    legalpriv_s2_1_heading: "2.1 Información que Usted Proporciona",
    legalpriv_s2_li_contact: "Datos de contacto: nombre, dirección de correo electrónico, número de teléfono, nombre de la empresa",
    legalpriv_s2_li_account: "Información de la cuenta: nombre de usuario, contraseña (cifrada mediante hash), preferencias",
    legalpriv_s2_li_business: "Información empresarial: tipo de empresa, sector de actividad, tamaño de la empresa",
    legalpriv_s2_li_communications: "Comunicaciones: mensajes enviados a través de nuestros formularios de contacto o canales de soporte",
    legalpriv_s2_li_payment: "Información de pago: procesada por nuestros proveedores de servicios de pago (no almacenamos los datos de la tarjeta)",
    legalpriv_s2_2_heading: "2.2 Datos Recopilados Automáticamente",
    legalpriv_s2_li_usage: "Datos de uso: páginas visitadas, funciones utilizadas, tiempo de permanencia, datos de navegación (clickstream)",
    legalpriv_s2_li_technical: "Datos técnicos: dirección IP, tipo de navegador, tipo de dispositivo, sistema operativo",
    legalpriv_s2_li_cookies: "Cookies y tecnologías de seguimiento similares (consulte nuestra <a href=\"cookies.html\" style=\"color:var(--blue);\">Política de Cookies</a>)",
    legalpriv_s3_heading: "3. Base Jurídica del Tratamiento",
    legalpriv_s3_intro: "De conformidad con el artículo 6 del RGPD, tratamos sus datos sobre la base de los siguientes fundamentos jurídicos:",
    legalpriv_s3_basis_contract_label: "Necesidad contractual (Art. 6.1.b):",
    legalpriv_s3_basis_contract_desc: "Para prestar nuestros servicios y cumplir con nuestras obligaciones contractuales frente a usted.",
    legalpriv_s3_basis_legitimate_label: "Interés legítimo (Art. 6.1.f):",
    legalpriv_s3_basis_legitimate_desc: "Para mejorar nuestros servicios, prevenir el fraude y garantizar la seguridad.",
    legalpriv_s3_basis_consent_label: "Consentimiento (Art. 6.1.a):",
    legalpriv_s3_basis_consent_desc: "Para comunicaciones de marketing y cookies no esenciales (cuando se haya obtenido de forma expresa).",
    legalpriv_s3_basis_legal_label: "Obligación legal (Art. 6.1.c):",
    legalpriv_s3_basis_legal_desc: "Para cumplir con las leyes aplicables y los requisitos regulatorios.",
    legalpriv_s4_heading: "4. Cómo Utilizamos Sus Datos",
    legalpriv_s4_li_provide: "Para prestar y gestionar nuestros servicios y plataformas de IA",
    legalpriv_s4_li_payments: "Para procesar pagos y gestionar suscripciones",
    legalpriv_s4_li_communicate: "Para comunicarnos con usted en relación con su cuenta y nuestros servicios",
    legalpriv_s4_li_notifications: "Para enviar notificaciones del servicio y (con su consentimiento) comunicaciones de marketing",
    legalpriv_s4_li_analyze: "Para analizar y mejorar nuestros productos y servicios",
    legalpriv_s4_li_fraud: "Para detectar y prevenir fraudes, abusos e incidentes de seguridad",
    legalpriv_s4_li_compliance: "Para cumplir con las obligaciones legales y los requisitos regulatorios",
    legalpriv_s5_heading: "5. Cesión de Datos y Subencargados del Tratamiento",
    legalpriv_s5_intro: "No vendemos, alquilamos ni comercializamos datos personales. Solo compartimos datos con subencargados de confianza necesarios para la prestación del servicio, en virtud de los correspondientes acuerdos de protección de datos:",
    legalpriv_s5_th_subprocessor: "Subencargado",
    legalpriv_s5_th_purpose: "Finalidad",
    legalpriv_s5_th_location: "Ubicación",
    legalpriv_s5_td_aws_name: "BB Cloud",
    legalpriv_s5_td_aws_purpose: "Alojamiento e infraestructura en la nube",
    legalpriv_s5_td_aws_location: "EE. UU. / UE",
