    cloud_db_eyebrow: "Bases de Datos",
    cloud_db_title: "Bases de datos gestionadas. Configuración cero.",
    cloud_db_desc: "Aprovisiona una base de datos lista para producción en segundos. Copias de seguridad automatizadas, replicación, conexiones privadas y un editor de consultas integrado.",
    cloud_db_postgres_desc: "Base de datos relacional principal. Niveles compartido, gestionado y dedicado. Agrupación de conexiones, réplicas de lectura y recuperación a un punto en el tiempo.",
    cloud_db_redis_desc: "Almacén de datos en memoria para gestión de sesiones, caché, colas y pub/sub en tiempo real. Opciones de persistencia disponibles.",
    cloud_db_vector_title: "Base de Datos Vectorial",
