    cloud_db_mongo_desc: "Base de datos de documentos para esquemas flexibles. Compatible con drivers y ODMs existentes de MongoDB.",
    cloud_db_queryeditor_title: "Editor de Consultas",
    cloud_db_queryeditor_desc: "Editor SQL desde el navegador con resaltado de sintaxis, historial de consultas, planes de ejecución y exportación de datos. No requiere cliente aparte.",
    cloud_ai_title: "Despliega Agentes de IA. No infraestructura.",
    cloud_ai_desc1: "Cloud AI dota a tus aplicaciones de agentes inteligentes sin necesidad de gestionar infraestructura de IA. El Blue Model Router selecciona automáticamente el mejor modelo de IA para cada tarea según coste, velocidad, privacidad y complejidad.",
    cloud_ai_desc2: "Tú despliegas agentes. La plataforma gestiona la selección de modelos, la limitación de tasa, el failover, el seguimiento de costes y el cumplimiento normativo. Tu aplicación llama a un único endpoint.",
    cloud_ai_router_desc: "Enruta cada solicitud al modelo óptimo según: umbral de coste · velocidad de respuesta · política de privacidad de datos · tipo de tarea · idioma · longitud de contexto.",
