    home_about_title: "AI-First. Enterprise-niveau.<br>Gebouwd voor LATAM & EMEA.",
    home_about_desc: "Blue Bridge Global Connection is een enterprise-technologiebedrijf met activiteiten in Costa Rica, Colombia en België. Wij bouwen AI Workforces, maatwerksoftware, automatiseringsplatforms en cloudinfrastructuur waarmee bedrijven op het hoogste niveau kunnen concurreren.",
