    solhub_ai_workforce_desc: "Zet teams van autonome AI-agents in die 24/7 actief zijn binnen uw volledige bedrijfsvoering. Elke agent is gespecialiseerd in een domein en werkt samen met de anderen via georkestreerde workflows.",
    solhub_ai_agents_desc: "Op maat gemaakte intelligente agents, getraind op uw bedrijfscontext. Geïntegreerd met uw bestaande systemen via API. Ingezet op uw eigen infrastructuur of door ons beheerd.",
    solhub_support_desc: "AI-supportagents die klantvragen ogenblikkelijk oplossen via alle kanalen. Verzorgen Tier 1- en Tier 2-support en escaleren pas naar menselijke medewerkers wanneer dat echt nodig is.",
    solhub_voice_desc: "Intelligente telefoonagents aangedreven door Twilio. Behandelen inkomende gesprekken, leiden aanvragen door, nemen boekingen aan en lossen problemen op met een natuurlijke, mensachtige conversatie.",
    solhub_booking_desc: "Volledige platformen voor boekings- en afsprakenbeheer. AI-gestuurde planning, geautomatiseerde herinneringen, betalingsverwerking en CRM-integratie.",
    solhub_crm_desc: "Zakelijke CRM-systemen op maat van uw sector. AI-gestuurde leadscoring, pipelinebeheer, geautomatiseerde opvolging en omzetanalyse.",
    solhub_automation_desc: "End-to-end automatisering van bedrijfsprocessen. Verbind uw tools, gegevensbronnen en teams tot intelligente workflows die automatisch worden uitgevoerd.",
    solhub_software_desc: "Op maat gemaakte bedrijfssoftware, gebouwd met een moderne cloud-native architectuur. FastAPI-backends, Next.js-frontends, PostgreSQL-databases en Docker-implementatie.",
    solhub_web_desc: "Zakelijke websites en webapplicaties. Met prestaties als prioriteit, geoptimaliseerd voor SEO, toegankelijk volgens WCAG en ontworpen om bezoekers om te zetten in klanten.",
    solhub_cloud_desc: "Ontwerp, implementatie en beheer van BB Cloud-infrastructuur. Veilige, schaalbare en kostenoptimale cloudarchitectuur voor zakelijke workloads van elke omvang.",
