    about_breadcrumb_home: "Home",
    about_breadcrumb_current: "Over Ons",
    about_mission_label: "Onze Missie",
    about_mission_title: "De Brug Tussen Business en AI",
    about_mission_p1: "Blue Bridge bestaat om AI van bedrijfsniveau toegankelijk te maken voor organisaties van elke omvang in Amerika en Europa. Wij geloven dat AI voor uw bedrijf moet werken — niet andersom.",
    about_mission_p2: "Wij ontwerpen en bouwen AI-systemen die naadloos integreren in bestaande activiteiten, de taal van uw sector spreken en uw gegevens en de privacy van uw klanten respecteren.",
    about_mission_p3: "Ons team van engineers, AI-specialisten en domeinexperts is actief in drie landen — met wereldwijde technologische expertise gecombineerd met kennis van de lokale markt.",
    about_mission_card1_title: "Leiderschap in LATAM",
    about_mission_card1_desc: "Met hoofdkantoor in Costa Rica en activiteiten in Colombia bedienen wij bedrijven in heel Latijns-Amerika met diepgaande kennis van de regionale markt.",
    about_mission_card2_title: "Aanwezigheid in EMEA",
    about_mission_card2_desc: "Kantoor in België dat Europese ondernemingen bedient met AVG-conforme AI-oplossingen en systemen die klaar zijn voor de EU AI Act.",
    about_mission_card3_title: "Partnerschapsbenadering",
    about_mission_card3_desc: "Wij werken als een verlengstuk van uw team, niet enkel als leverancier. Langetermijnrelaties gebouwd op transparantie en resultaten.",
    about_capabilities_label: "Wat Wij Doen",
    about_capabilities_title: "Onze Kerncompetenties",
    about_capabilities_desc: "AI-oplossingen voor ondernemingen over het volledige technologiespectrum.",
    about_cap_agents_title: "Aangepaste AI Agenten",
    about_cap_agents_desc: "Intelligente agenten getraind op uw bedrijfscontext, geïntegreerd met uw systemen en ingezet op uw infrastructuur.",
    about_cap_voice_title: "Stem AI",
    about_cap_voice_desc: "Telefonische AI-agenten aangedreven door Twilio die inkomende oproepen afhandelen, vragen doorsturen en afspraken inplannen met natuurlijke spraak.",
    about_cap_automation_title: "Bedrijfsautomatisering",
    about_cap_automation_desc: "End-to-end workflowautomatisering die CRM, ERP, communicatieplatforms en aangepaste systemen met elkaar verbindt.",
    about_cap_crm_title: "CRM-ontwikkeling",
    about_cap_crm_desc: "Aangepaste CRM-platforms gebouwd voor uw specifieke sector, met AI-gestuurde inzichten, leadscoring en pipelinebeheer.",
    about_cap_cloud_title: "Cloudinfrastructuur",
    about_cap_cloud_desc: "Ontwerp, implementatie en beheer van BB Cloud-native architectuur. Schaalbaar, veilig en kostengeoptimaliseerd voor bedrijfskritische workloads.",
    about_cap_booking_title: "Boekingsplatforms",
    about_cap_booking_desc: "Intelligente afspraak- en reserveringssystemen voor gezondheidszorg, horeca en professionele diensten.",
    about_cap_healthcare_title: "Zorgtechnologie",
    about_cap_healthcare_desc: "Klinische AI, patiëntenbeheer, integratie van elektronische patiëntendossiers en HIPAA-bewuste zorgplatforms.",
    about_cap_restaurant_title: "Restaurantoplossingen",
    about_cap_restaurant_desc: "RestOS-platform voor restaurantactiviteiten: kassasysteem, reserveringsbeheer, personeelsplanning, klantenloyaliteit.",
    about_cap_enterprise_title: "Enterprise AI",
    about_cap_enterprise_desc: "Grootschalige AI-transformatieprogramma's voor ondernemingen: automatisering over meerdere afdelingen, changemanagement, training.",
