    about_values_label: "Waarden",
    about_values_title: "Waar Wij Voor Staan",
    about_value_transparency_title: "Transparantie",
    about_value_transparency_desc: "Wij zijn open over onze technologie, onze processen en onze beperkingen. Geen zwarte dozen, geen verborgen kosten.",
    about_value_security_title: "Veiligheid Voorop",
    about_value_security_desc: "Beveiliging op bedrijfsniveau is geen optie. Elk systeem dat wij bouwen wordt ontworpen met beveiliging als eerste principe.",
    about_value_partnership_title: "Partnerschap",
    about_value_partnership_desc: "Wij slagen wanneer onze klanten slagen. Langetermijnrelaties gebouwd op vertrouwen, verantwoordelijkheid en resultaten.",
    about_value_excellence_title: "Excellentie",
    about_value_excellence_desc: "Wij hanteren hoge standaarden voor codekwaliteit, design, prestaties en communicatie met de klant.",
    about_value_responsible_title: "Verantwoorde AI",
    about_value_responsible_desc: "AI die de mensheid ten goede komt. Wij weigeren actief toepassingen die mensen schaden, discrimineren of de privacy schenden.",
    about_value_local_title: "Lokale Kennis",
    about_value_local_desc: "Wereldwijde technologie met kennis van de lokale markt. Wij begrijpen de bedrijfscultuur, regelgeving en taal van elke markt die wij bedienen.",
    about_cta_label: "Werk met Ons",
    about_cta_team_btn: "Maak Kennis met Ons Team",
    solva_hero_desc: "Transformeer uw telefoonkanaal met AI-medewerkers die 24/7 oproepen beantwoorden, natuurlijk spreken, context begrijpen en taken voltooien — van het inplannen van afspraken tot het oplossen van supportvragen.",
    solva_hero_cta: "Stem AI implementeren",
    solva_features_label: "Functies",
    solva_features_title: "Wat is Inbegrepen",
    solva_feature_natural_title: "Natuurlijk Gesprek",
    solva_feature_natural_desc: "Geavanceerde spraak-AI die context begrijpt, onderbrekingen verwerkt en natuurlijk reageert — geen robotachtige IVR.",
    solva_feature_twilio_title: "Aangedreven door Twilio",
    solva_feature_twilio_desc: "Gebouwd op de zakelijke telefonie-infrastructuur van Twilio, met wereldwijd bereik en een beschikbaarheid van 99,99%.",
    solva_feature_number_title: "Toegewezen Nummer",
    solva_feature_number_desc: "Uw AI-medewerker beschikt over een eigen toegewezen telefoonnummer. Klanten bellen en communiceren rechtstreeks.",
    solva_feature_recording_title: "Gespreksopname",
    solva_feature_recording_desc: "Alle gesprekken worden automatisch opgenomen en getranscribeerd. Volledige gespreksgeschiedenis beschikbaar.",
    solva_feature_booking_title: "Reserveringsintegratie",
    solva_feature_booking_desc: "De Stem AI-medewerker kan beschikbaarheid controleren, afspraken boeken en bevestigings-sms's versturen tijdens hetzelfde gesprek.",
    solva_feature_crm_title: "CRM-integratie",
    solva_feature_crm_desc: "Elk gesprek wordt geregistreerd in uw CRM, met transcript, intentie en resultaat automatisch vastgelegd.",
    solva_usecases_label: "Gebruiksscenario's",
    solva_usecases_title: "Veelvoorkomende Toepassingen",
    solva_usecase_appointment: "Afspraken boeken",
    solva_usecase_order_status: "Updates over bestelstatus",
    solva_usecase_patient_intake: "Patiëntenintake",
    solva_usecase_hotel: "Hotelreserveringen",
    solva_usecase_customer_service: "Klantenservice",
    solva_usecase_sales: "Verkoopkwalificatie",
    solba_hero_desc: "Een volledig reserverings- en afsprakenplatform met AI als kern. Uw klanten kunnen 24/7 boeken via web, WhatsApp, telefoon of elk ander kanaal — zonder enige menselijke tussenkomst.",
    solba_hero_cta: "Bouw uw Reserveringsplatform",
    solba_features_label: "Functies",
    solba_features_title: "Wat is Inbegrepen",
    solba_feature_scheduling_title: "Slimme Planning",
    solba_feature_scheduling_desc: "AI houdt rekening met beschikbaarheid, duur van de dienst, resourcebeperkingen en voorkeuren om optimale tijdstippen voor te stellen.",
    solba_feature_reminders_title: "Geautomatiseerde Herinneringen",
    solba_feature_reminders_desc: "Herinneringen via sms, WhatsApp en e-mail op aangepaste intervallen. Vermindert no-shows drastisch.",
    solba_feature_payment_title: "Online Betaling",
    solba_feature_payment_desc: "Int aanbetalingen of volledige betaling bij het boeken. Automatische verwerking van terugbetalingen bij annuleringen.",
    solba_feature_multilocation_title: "Meerdere Locaties",
    solba_feature_multilocation_desc: "Eén platform voor het beheren van boekingen over meerdere locaties, medewerkers en type diensten.",
    solba_feature_calendar_title: "Agendasynchronisatie",
    solba_feature_calendar_desc: "Tweerichtingssynchronisatie met Google Agenda, Outlook en Apple Kalender. Nooit meer dubbele boekingen.",
    solba_feature_analytics_title: "Analytics",
    solba_feature_analytics_desc: "Bezettingsgraden, omzet per tijdslot, no-show-trends en klantretentiecijfers in één oogopslag.",
    solba_usecases_label: "Gebruiksscenario's",
