    solba_usecase_class: "Inschrijvingen voor lessen",
    solcrm_hero_desc: "Een CRM specifiek gebouwd voor uw bedrijf — geen generieke tool die u moet aanpassen. AI-gestuurde inzichten, geautomatiseerde opvolging en een volledig overzicht van elke klantrelatie.",
    solcrm_hero_cta: "Bouw uw CRM",
    solcrm_features_label: "Functies",
    solcrm_features_title: "Wat is Inbegrepen",
    solcrm_feature_leadscoring_title: "AI Lead Scoring",
    solcrm_feature_leadscoring_desc: "Machine learning-modellen scoren leads op basis van gedrag, demografische gegevens en historische data.",
    solcrm_feature_pipeline_title: "Pipelinebeheer",
    solcrm_feature_pipeline_desc: "Visuele pipeline met geautomatiseerde fase-voortgang op basis van klantacties en medewerkersinteracties.",
    solcrm_feature_followup_title: "Geautomatiseerde Opvolging",
    solcrm_feature_followup_desc: "Activeer automatisch e-mailreeksen, WhatsApp-berichten en taken op basis van pipelinefase en verstreken tijd.",
    solcrm_feature_360view_title: "360° Klantoverzicht",
    solcrm_feature_360view_desc: "Elke interactie, elk document, elke communicatie en transactie in één centraal klantdossier.",
    solcrm_feature_revenue_title: "Omzetanalyse",
    solcrm_feature_revenue_desc: "Voorspel omzet, volg de realisatie van quota en identificeer risicovolle deals in real-time.",
    solcrm_feature_integration_title: "Integratiehub",
    solcrm_feature_integration_desc: "Verbind met e-mail, agenda, telefonie, WhatsApp, facturatie en elk aangepast systeem via API.",
