    beapartner_hero_desc: "Verwijs klanten door, verkoop Blue Bridge producten, of bouw een volledige markt op als Onafhankelijke Commerciële Partner — met terugkerende inkomsten, echte technologietoegang en toegewijde commerciële ondersteuning.",
    beapartner_hero_cta: "Solliciteer als Partner",
    beapartner_program_label: "Het Programma",
    beapartner_program_title: "Een Wereldwijd Commercieel Netwerk",
    beapartner_program_desc: "Met het Blue Bridge Partnerprogramma kunnen zelfstandige professionals, bureaus, adviesbureaus en bedrijven klanten doorverwijzen, actief Blue Bridge producten verkopen, of volledige markten en sectoren ontwikkelen — en zo terugkerende, resultaatgerichte commerciële inkomsten verdienen zonder ooit zelf technologie te hoeven bouwen.",
    beapartner_program_card1_title: "Terugkerende Inkomsten",
    beapartner_program_card1_desc: "Verdien commissie op elke klant die u aanbrengt, zolang de commerciële overeenkomst actief blijft — geen eenmalige verwijzingsvergoeding.",
    beapartner_program_card2_title: "Echte Technologietoegang",
    beapartner_program_card2_desc: "Verkoop productierijpe AI- en softwareproducten die al draaien voor echte klanten — ARLINOS, BBOS en meer — zonder dat u zelf hoeft te ontwikkelen.",
    beapartner_program_card3_title: "Commerciële Ondersteuning",
    beapartner_program_card3_desc: "Pitch decks, brochures, demovideo's, verkoopscripts, bezwaarafhandeling en case studies — plus een partnerportaal om elke deal en uitbetaling te volgen.",
    beapartner_levels_label: "Partnerniveaus",
    beapartner_levels_title: "Vier Manieren om Partner te Worden",
    beapartner_levels_desc: "Elk niveau is ontworpen voor een ander type commerciële relatie. Commissiestructuren en voorwaarden worden privé besproken zodra uw aanvraag is beoordeeld.",
    beapartner_level1_badge: "Niveau 1",
    beapartner_level1_title: "Verwijzingspartner",
    beapartner_level1_desc: "Voor personen of bedrijven die Blue Bridge introduceren bij een potentiële klant. U legt het contact — wij doen de rest.",
