    beapartner_level1_item2: "Commissie voor elke klant die converteert",
    beapartner_level1_item3: "Geen verkoopverplichtingen of quota",
    beapartner_level2_badge: "Niveau 2",
    beapartner_level2_title: "Verkooppartner",
    beapartner_level2_desc: "Voor partners die actief Blue Bridge producten verkopen. Beheer uw eigen pipeline, uw eigen klanten, en verdien terugkerende commissie.",
