    beapartner_level2_item3: "Inzicht in uw verkopen en commissies",
    beapartner_level3_badge: "Niveau 3",
    beapartner_level3_title: "Strategische Partner",
    beapartner_level3_desc: "Voor partners die een volledige markt, sector of regio ontwikkelen. Bouw uw eigen klantenportfolio op en breng uw eigen subpartners mee.",
    beapartner_level3_item1: "Beheer een portfolio van klanten en subpartners",
