    beapartner_level3_item3: "Geavanceerde rapportage en marketingmateriaal",
    beapartner_level4_badge: "Niveau 4",
    beapartner_level4_title: "Investeringspartner",
    beapartner_level4_desc: "Voorbehouden aan uitzonderlijke, strategische bijdragen — aanzienlijke investering, een volledig ontwikkelde markt, of gezamenlijk ontwikkelde technologie.",
    beapartner_level4_item1: "Per geval beoordeeld, niet automatisch toegekend",
