    beapartner_why_card1_title: "Onafhankelijke Commerciële Partner",
    beapartner_why_card1_desc: "U opereert als een onafhankelijke onderneming — u beheert uw eigen tijd, uw eigen fiscale verplichtingen en uw eigen commerciële activiteit. Er is geen salaris, geen vast rooster en geen arbeidsrelatie met Blue Bridge; uw inkomen hangt volledig af van commerciële resultaten.",
