    solsw_feature_cloud_native_desc: "Vanaf dag één ontworpen voor BB Cloud: elastisch compute, beheerde databases, objectopslag, wereldwijd CDN, serverless functies en containerorkestratie voor gecontaineriseerde workloads.",
    solsw_feature_agile_title: "Agile Levering",
