    pricing_addon_actions_desc: "50.000 extra AI-acties per maand voor operaties met een hoog volume.",
    pricing_addon_priority_support_title: "Prioritaire Ondersteuning Upgrade",
    pricing_addon_priority_support_desc: "Ondersteuning via e-mail, chat en telefoon met 2 uur SLA. Beschikbaar bij het Starter-plan.",
    pricing_faq_label: "FAQ",
    pricing_faq_title: "Veelgestelde Vragen",
    pricing_faq_q1: "Kan ik mijn plan op elk moment wijzigen?",
    pricing_faq_a1: "Ja. Upgrades gaan onmiddellijk in. Downgrades gaan in bij het begin van uw volgende factureringscyclus. Geen contractverplichting bij maandelijkse plannen.",
    pricing_faq_q2: "Is er een gratis proefperiode?",
    pricing_faq_a2: "Wij bieden een proefperiode van 14 dagen aan voor de Starter- en Professional-plannen. Vraag dit aan via het contactformulier — wij richten een live omgeving in met uw bedrijfsgegevens.",
    pricing_faq_q3: "Wat telt als een AI-actie?",
    pricing_faq_a3: "Elke taak die door een AI-medewerker wordt uitgevoerd: een e-mail versturen, een bericht beantwoorden, een afspraak boeken, een rapport genereren of een workflowstap voltooien.",
    pricing_faq_q4: "Zijn integraties inbegrepen of brengen ze extra kosten met zich mee?",
    pricing_faq_a4: "Starter omvat 1 integratie. Professional omvat onbeperkte integraties. Alle standaardconnectoren (WhatsApp, Gmail, Outlook, Google Agenda) zijn inbegrepen zonder extra kosten.",
    pricing_faq_q5: "Bieden jullie kortingen voor non-profitorganisaties of startups?",
    pricing_faq_a5: "Ja. 25% korting voor geregistreerde non-profitorganisaties en startups in een vroege fase (met een omzet onder $500.000). Neem contact op met sales@bluebridge.es met de bijbehorende documentatie.",
    pricing_faq_q6: "Is er een opstartkost?",
    pricing_faq_a6: "Geen opstartkosten bij Starter of Professional. Enterprise-plannen omvatten een eenmalige implementatiekost, geoffreerd op basis van de scope, inclusief volledige onboarding, integratie en testen.",
    pricing_faq_cta_text: "Nog vragen? Praat rechtstreeks met ons team.",
