    legalpriv_title: "Privacybeleid",
    legalpriv_desc: "Dit Privacybeleid legt uit hoe THE BLUE BRIDGE CONNECTION CO SOCIEDAD DE RESPONSABILIDAD LIMITADA, handelend onder de naam Blue Bridge Global Connection, persoonsgegevens verzamelt, gebruikt en beschermt.",
    legalpriv_s1_heading: "1. Wie Wij Zijn",
    legalpriv_s1_intro: "De verwerkingsverantwoordelijke voor uw persoonsgegevens is:",
    legalpriv_s1_identity_details: "Handelsnaam: <strong>Blue Bridge Global Connection</strong><br>Registratienummer: 3-102-880-591<br>Maatschappelijke Zetel: Alpha Legal, Boulevard Dent, Barrio Dent, San Pedro, Montes de Oca, San José 11501, Costa Rica<br>E-mail: <a href=\"mailto:privacy@bluebridge.es\" style=\"color:var(--blue);\">privacy@bluebridge.es</a>",
    legalpriv_s2_heading: "2. Gegevens die Wij Verzamelen",
