    legalpriv_s2_li_cookies: "Cookies en soortgelijke trackingtechnologieën (zie ons <a href=\"cookies.html\" style=\"color:var(--blue);\">Cookiebeleid</a>)",
    legalpriv_s3_heading: "3. Rechtsgrond voor Verwerking",
    legalpriv_s3_intro: "Op grond van artikel 6 van de AVG verwerken wij uw gegevens op basis van de volgende rechtsgronden:",
    legalpriv_s3_basis_contract_label: "Noodzaak voor de uitvoering van een overeenkomst (Art. 6.1.b):",
    legalpriv_s3_basis_contract_desc: "Om onze diensten te leveren en onze contractuele verplichtingen jegens u na te komen.",
    legalpriv_s3_basis_legitimate_label: "Gerechtvaardigd belang (Art. 6.1.f):",
    legalpriv_s3_basis_legitimate_desc: "Om onze diensten te verbeteren, fraude te voorkomen en de veiligheid te waarborgen.",
