    legalpriv_s4_li_compliance: "Om te voldoen aan wettelijke verplichtingen en regelgevende vereisten",
    legalpriv_s5_heading: "5. Gegevensdeling en Subverwerkers",
    legalpriv_s5_intro: "Wij verkopen, verhuren of verhandelen geen persoonsgegevens. Wij delen gegevens uitsluitend met vertrouwde subverwerkers die noodzakelijk zijn voor de dienstverlening, op basis van passende gegevensbeschermingsovereenkomsten:",
