    legalpriv_s5_td_google_location: "VS",
    legalpriv_s5_footnote: "Alle internationale doorgiften van gegevens zijn onderworpen aan passende waarborgen, met inbegrip van Standaardcontractbepalingen (SCC's), waar van toepassing.",
    legalpriv_s6_heading: "6. Bewaring van Gegevens",
    legalpriv_s6_li_account: "<strong>Accountgegevens:</strong> worden bewaard gedurende de looptijd van de overeenkomst plus 3 jaar",
    legalpriv_s6_li_contact_form: "<strong>Inzendingen via het contactformulier:</strong> worden 2 jaar bewaard vanaf de datum van verzending",
