    legalpriv_s6_li_security_logs: "<strong>Beveiligingslogs:</strong> worden 12 maanden bewaard",
    legalpriv_s7_heading: "7. Uw Rechten Onder de AVG",
    legalpriv_s7_intro: "Op grond van de AVG en de toepasselijke privacywetgeving beschikt u over de volgende rechten:",
    legalpriv_s7_right_access_title: "Recht van Inzage",
