    cloud_ai_title: "Implementeer AI Agenten. Geen infrastructuur.",
    cloud_ai_desc1: "Cloud AI geeft je applicaties intelligente agenten zonder dat je AI-infrastructuur hoeft te beheren. De Blue Model Router selecteert automatisch het beste AI-model voor elke taak op basis van kosten, snelheid, privacy en complexiteit.",
