    legalcookies_breadcrumb_current: "Cookiebeleid",
    legalcookies_label: "Juridisch",
    legalcookies_title: "Cookiebeleid",
    legalcookies_intro: "Dit Cookiebeleid legt uit hoe Blue Bridge Global Connection cookies en soortgelijke technologieën gebruikt op onze website en platformen.",
    legalcookies_h2_what_are_cookies: "1. Wat zijn cookies?",
    legalcookies_what_are_cookies_body: "Cookies zijn kleine tekstbestanden die op uw apparaat worden geplaatst wanneer u een website bezoekt. Ze helpen websites uw voorkeuren te onthouden, u ingelogd te houden en te begrijpen hoe bezoekers de site gebruiken. Vergelijkbare technologieën omvatten webbakens, pixels en lokale opslag.",
    legalcookies_h2_categories: "2. Cookiecategorieën",
    legalcookies_cat_necessary_title: "Strikt noodzakelijke cookies",
    legalcookies_badge_always_active: "Altijd actief",
    legalcookies_cat_necessary_desc: "Deze cookies zijn essentieel voor de werking van de website en kunnen niet worden uitgeschakeld. Ze worden meestal geplaatst als reactie op handelingen die u verricht, zoals inloggen of formulieren invullen.",
    legalcookies_th_cookie: "Cookie",
    legalcookies_th_purpose: "Doel",
    legalcookies_th_duration: "Duur",
    legalcookies_purpose_auth_session: "Authenticatiesessie van de gebruiker",
    legalcookies_duration_session: "Sessie",
    legalcookies_purpose_csrf: "Beveiligingstoken (CSRF-bescherming)",
    legalcookies_purpose_consent_pref: "Cookietoestemmingsvoorkeur",
    legalcookies_duration_12months: "12 maanden",
    legalcookies_purpose_lang_pref: "Taalvoorkeur",
    legalcookies_cat_analytics_title: "Prestatie- en analysecookies",
    legalcookies_badge_consent_required: "Toestemming vereist",
    legalcookies_cat_analytics_desc: "Deze cookies helpen ons te begrijpen hoe bezoekers onze website gebruiken door anonieme statistische informatie te verzamelen.",
    legalcookies_th_provider: "Aanbieder",
    legalcookies_purpose_user_id_anon: "Gebruikersidentificatie (geanonimiseerd)",
    legalcookies_duration_2years: "2 jaar",
    legalcookies_purpose_session_tracking: "Sessietracking",
    legalcookies_purpose_session_diff: "Sessiedifferentiatie",
    legalcookies_duration_24hours: "24 uur",
    legalcookies_cat_functional_title: "Functionele cookies",
    legalcookies_cat_functional_desc: "Deze cookies maken verbeterde functionaliteit en personalisatie mogelijk.",
    legalcookies_purpose_theme_pref: "Voorkeur voor UI-thema (donker/licht)",
    legalcookies_purpose_last_conv: "Status van laatste gesprek (klantenportaal)",
    legalcookies_cat_marketing_title: "Marketingcookies",
    legalcookies_cat_marketing_desc: "Momenteel gebruiken wij geen marketing- of advertentiecookies. Als wij deze in de toekomst invoeren, zullen wij dit beleid bijwerken en uw toestemming vragen.",
    legalcookies_h2_managing: "3. Uw cookies beheren",
    legalcookies_managing_intro: "U beschikt over verschillende opties om het gebruik van cookies te beheren:",
    legalcookies_manage_banner: "<strong>Cookiebanner:</strong> Bij uw eerste bezoek aan onze site kunt u ervoor kiezen niet-essentiële cookies te accepteren of te weigeren",
    legalcookies_manage_browser: "<strong>Browserinstellingen:</strong> De meeste browsers stellen u in staat cookies te weigeren of te verwijderen via hun instellingen",
    legalcookies_manage_ga_optout: "<strong>Google Analytics opt-out:</strong> Installeer de browsertoevoeging van Google Analytics om gegevensverzameling te voorkomen",
    legalcookies_manage_contact: "<strong>Neem contact met ons op:</strong> Mail naar privacy@bluebridge.es om uw toestemming te resetten of verwijdering van gegevens aan te vragen",
    legalcookies_note_label: "Let op:",
    legalcookies_note_text: "Het uitschakelen van strikt noodzakelijke cookies heeft gevolgen voor de werking van de website en kan verhinderen dat u kunt inloggen op uw account.",
    legalcookies_h2_third_party: "4. Cookies van derden",
    legalcookies_third_party_body: "Sommige cookies op onze site worden geplaatst door diensten van derden. Deze derde partijen hebben hun eigen privacybeleid, dat wij u aanraden te raadplegen: <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--blue);\">Privacybeleid van Google</a>.",
    legalcookies_h2_updates: "5. Wijzigingen aan dit beleid",
    legalcookies_updates_body: "Wij kunnen dit Cookiebeleid bijwerken wanneer wij ons cookiegebruik wijzigen of als reactie op wijzigingen in de privacyregelgeving. De datum bovenaan deze pagina geeft aan wanneer het beleid voor het laatst is bijgewerkt.",
    legalcookies_questions_title: "Vragen?",
    legalcookies_questions_body: "Neem contact op met ons privacyteam via <a href=\"mailto:privacy@bluebridge.es\" style=\"color:var(--blue);\">privacy@bluebridge.es</a> of raadpleeg ons <a href=\"privacy-policy.html\" style=\"color:var(--blue);\">Privacybeleid</a> voor meer informatie over hoe wij uw persoonsgegevens verwerken.",
    legalcookies_reset_button: "Mijn cookievoorkeuren resetten",
    legalsec_breadcrumb_home: "Home",
    legalsec_breadcrumb_legal: "Juridisch",
    legalsec_breadcrumb_current: "Beveiliging",
    legalsec_label_hero: "Beveiliging",
    legalsec_title: "Beveiligingsoverzicht",
    legalsec_intro: "Een transparante beschrijving van de technische en organisatorische beveiligingsmaatregelen die de systemen van Blue Bridge, klantgegevens en de integriteit van de dienstverlening beschermen.",
    legalsec_label_infrastructure: "Infrastructuur",
    legalsec_infra_title: "Cloudinfrastructuur",
    legalsec_infra_desc: "Alle productiesystemen van Blue Bridge draaien op BB Cloud, ons cloudplatform van bedrijfsniveau dat is gebouwd voor betrouwbaarheid op grote schaal.",
    legalsec_card_multiregion_title: "Multi-regio",
    legalsec_card_multiregion_desc: "Primair: Noord-Amerika (Virginia). EMEA: Europa (Ierland). Replicatie tussen regio's voor kritieke gegevens.",
    legalsec_card_cdn_title: "Wereldwijd CDN",
    legalsec_card_cdn_desc: "Wereldwijde contentlevering via ons CDN met meer dan 400 edge-locaties wereldwijd. DDoS-bescherming inbegrepen.",
    legalsec_card_vpc_title: "Privé-VPC",
    legalsec_card_vpc_desc: "Alle compute-resources draaien binnen een private Virtual Private Cloud. Geen directe openbare internettoegang tot backendsystemen.",
    legalsec_card_waf_title: "WAF-bescherming",
    legalsec_card_waf_desc: "Onze webapplicatiefirewall beschermt tegen de OWASP Top 10, SQL-injectie, XSS en bot-aanvallen.",
    legalsec_card_autoscaling_title: "Automatisch schalen",
    legalsec_card_autoscaling_desc: "Elastische infrastructuur schaalt automatisch mee om verkeerspieken op te vangen zonder verslechtering van de dienstverlening.",
    legalsec_card_iam_title: "IAM-beleid",
    legalsec_card_iam_desc: "Identity and Access Management met fijnmazige machtigingen. Geen wildcard IAM-beleid in productie.",
