    legalsec_h3_data_at_rest: "Gegevens in rust",
    legalsec_encrypt_rest_aes256: "AES-256-versleuteling voor alle opgeslagen gegevens (databases, bestanden, back-ups)",
    legalsec_encrypt_rest_kms: "Beheerde Key Management Service (KMS) voor het beheer van versleutelingssleutels",
    legalsec_encrypt_rest_postgres: "Beheerde PostgreSQL met versleuteling ingeschakeld op opslagniveau",
    legalsec_encrypt_rest_objectstorage: "Server-side versleuteling voor alle objectopslag",
    legalsec_encrypt_rest_redis: "Versleutelde Redis voor sessie- en cachegegevens",
    legalsec_h3_data_in_transit: "Gegevens in transit",
    legalsec_transit_tls: "TLS 1.3 verplicht voor alle HTTP-verbindingen (overal HTTPS)",
    legalsec_transit_hsts: "HTTP Strict Transport Security (HSTS)-headers geconfigureerd",
    legalsec_transit_cert_mgmt: "Beheerde certificaatdienst voor SSL/TLS-certificaten",
