    legalsec_transit_cert_pinning: "TLS-certificaatpinning voor mobiele applicaties",
    legalsec_label_access_control: "Toegangscontrole",
    legalsec_h2_access_control: "Rolgebaseerde toegangscontrole",
    legalsec_card_rbac_title: "RBAC",
    legalsec_card_rbac_desc: "Rolgebaseerde toegangscontrole met granulaire machtigingen. Elke gebruiker en elk systeem heeft de minimaal vereiste toegang (principe van minimale rechten).",
    legalsec_card_mfa_title: "Multi-factor authenticatie",
    legalsec_card_mfa_desc: "MFA is vereist voor alle administratieve toegang. TOTP- en hardwaresleutelopties beschikbaar voor zakelijke klanten.",
    legalsec_card_apikey_title: "API-sleutelbeheer",
    legalsec_card_apikey_desc: "API-sleutels met een beperkte reikwijdte en vervalbeleid. Geautomatiseerde rotatie voor systeem-naar-systeem-inloggegevens.",
    legalsec_card_audit_title: "Auditlogging",
    legalsec_card_audit_desc: "Uitgebreid audittraject van alle toegang, wijzigingen en administratieve handelingen. Logs worden minimaal 12 maanden bewaard.",
    legalsec_card_zerotrust_title: "Zero-trust",
    legalsec_card_zerotrust_desc: "Zero-trust netwerkarchitectuur. Geen impliciet vertrouwen op basis van netwerklocatie. Alle toegang wordt continu geverifieerd.",
    legalsec_card_session_title: "Sessiebeheer",
    legalsec_card_session_desc: "JWT-tokens met korte vervaltijd. Automatische ongeldigmaking van sessies bij verdachte activiteit. Beveiligde cookie-attributen.",
    legalsec_label_data_protection: "Gegevensbescherming",
