    legalsec_label_monitoring: "Monitoring",
    legalsec_h2_monitoring: "24/7-monitoring",
    legalsec_card_sysmon_title: "Systeemmonitoring",
    legalsec_card_sysmon_desc: "Ons monitoringplatform volgt alle infrastructuurstatistieken: CPU, geheugen, schijf, netwerk en databaseprestaties. Waarschuwingen zijn geconfigureerd voor afwijkingen.",
    legalsec_card_secmon_title: "Beveiligingsmonitoring",
    legalsec_card_secmon_desc: "Intelligente dreigingsdetectie analyseert voortdurend activiteit. Netwerkflowlogs analyseren verkeerspatronen op verdachte activiteit.",
    legalsec_card_applog_title: "Applicatielogging",
    legalsec_card_applog_desc: "Gestructureerde logging met correlatie-ID's. Alle API-verzoeken worden gelogd. Realtime loganalyse met waarschuwingen bij pieken in foutpercentages.",
    legalsec_label_response: "Respons",
    legalsec_h2_incident_response: "Incidentrespons",
    legalsec_step1_title: "Detectie",
    legalsec_step1_desc: "Geautomatiseerde monitoring detecteert afwijkingen. Het beveiligingsteam wordt binnen enkele minuten gewaarschuwd via PagerDuty.",
    legalsec_step2_title: "Inperking",
    legalsec_step2_desc: "Onmiddellijke isolatie van getroffen systemen. WAF-regels worden bijgewerkt om aanvalsvectoren te blokkeren.",
    legalsec_step3_title: "Beoordeling",
    legalsec_step3_desc: "Analyse van de hoofdoorzaak en impactbeoordeling. Classificatie als P1/P2/P3 op basis van ernst.",
    legalsec_step4_title: "Kennisgeving",
    legalsec_step4_desc: "Getroffen klanten worden binnen 24 uur op de hoogte gebracht. AVG-inbreukmelding binnen 72 uur wanneer vereist.",
    legalsec_step5_title: "Herstel en evaluatie",
    legalsec_step5_desc: "Herstel van de dienstverlening. Een rapport na afloop van het incident wordt binnen 5 werkdagen aan zakelijke klanten geleverd.",
