    legalsec_sla_p4_value: "< 72 uur",
    legalsec_disclosure_title: "Verantwoorde openbaarmaking",
    legalsec_disclosure_intro: "Wij verwelkomen verantwoord beveiligingsonderzoek. Als u een kwetsbaarheid in onze systemen ontdekt, meld deze dan privé aan ons voordat u deze openbaar maakt.",
    legalsec_disclosure_commitment: "Wij verbinden ons ertoe: binnen 24 uur te bevestigen, binnen 5 werkdagen te reageren, en geen juridische stappen te ondernemen tegen te goeder trouw uitgevoerd onderzoek.",
    legalcomp_breadcrumb_compliance: "Naleving",
    legalcomp_hero_label: "Naleving",
    legalcomp_hero_title: "Naleving",
    legalcomp_hero_desc: "Onze regelgevingsnaleving op het gebied van GDPR, de EU AI Act, Privacy by Design, Security by Design en Verantwoorde AI.",
    legalcomp_overview_label: "Overzicht",
    legalcomp_overview_title: "Nalevingsstatus",
    legalcomp_overview_desc: "Realtime nalevingsstatus binnen onze belangrijkste regelgevende kaders.",
    legalcomp_badge_active_compliance: "Actieve Naleving",
    legalcomp_badge_in_preparation: "In Voorbereiding",
    legalcomp_badge_evaluating: "Wordt Geëvalueerd",
    legalcomp_card_gdpr_desc: "Algemene Verordening Gegevensbescherming (EU) 2016/679. Volledige naleving geïmplementeerd, met inbegrip van privacyverklaringen, verwerkersovereenkomsten (DPA's), procedures voor de rechten van betrokkenen en protocollen voor het melden van datalekken.",
    legalcomp_card_euaiact_desc: "Verordening (EU) 2024/1689. Actief in voorbereiding op naleving. Onze AI-systemen zijn geclassificeerd en op risico beoordeeld. Maatregelen voor menselijk toezicht en transparantie zijn reeds van kracht.",
    legalcomp_card_pbd_title: "Privacy by Design",
    legalcomp_card_pbd_desc: "Privacy wordt in al onze systemen en processen ingebouwd vanaf de ontwerpfase, en niet achteraf toegevoegd. Alle nieuwe functies ondergaan een privacy-impactbeoordeling.",
    legalcomp_card_sbd_title: "Security by Design",
    legalcomp_card_sbd_desc: "Beveiligingsvereisten worden vanaf de vroegste fasen in onze softwareontwikkelingscyclus ingebouwd. Threat modeling, beveiligde codereview en penetratietests zijn standaardpraktijk.",
    legalcomp_card_rai_title: "Verantwoorde AI",
    legalcomp_card_rai_desc: "Onze AI-ontwikkeling volgt principes van veiligheid, transparantie, eerlijkheid en menselijk toezicht. Wij hanteren een intern ethisch toetsingsproces voor AI bij elke nieuwe AI-implementatie.",
    legalcomp_card_iso_desc: "Wij evalueren momenteel ISO 27001-certificering voor ons Information Security Management System. Onze huidige praktijken sluiten aan bij de vereisten van ISO 27001.",
    legalcomp_gdpr_detail_title: "Details over GDPR-naleving",
    legalcomp_gdpr_implemented_title: "Wat Wij Hebben Geïmplementeerd",
