    legalcomp_pbd_sbd_label: "Principes",
    legalcomp_pbd_sbd_title: "Privacy en Security by Design",
    legalcomp_pbd_heading: "Privacy by Design (PbD)",
    legalcomp_pbd_intro: "Wij passen alle 7 fundamentele principes van Privacy by Design toe:",
    legalcomp_pbd_principle_proactive: "<strong style=\"color:var(--white);\">Proactief:</strong> Privacyproblemen worden geanticipeerd en voorkomen, niet achteraf verholpen",
    legalcomp_pbd_principle_default: "<strong style=\"color:var(--white);\">Standaard:</strong> Maximale privacybescherming is de standaardinstelling",
    legalcomp_pbd_principle_embedded: "<strong style=\"color:var(--white);\">Ingebed:</strong> Privacy is in het ontwerp verankerd, niet achteraf toegevoegd",
    legalcomp_pbd_principle_positivesum: "<strong style=\"color:var(--white);\">Positieve som:</strong> Privacy en beveiliging worden niet tegen elkaar afgewogen",
    legalcomp_pbd_principle_endtoend: "<strong style=\"color:var(--white);\">End-to-end:</strong> Privacy wordt gewaarborgd gedurende de volledige levenscyclus van de gegevens",
    legalcomp_pbd_principle_visibility: "<strong style=\"color:var(--white);\">Zichtbaarheid:</strong> Werkzaamheden zijn transparant en verifieerbaar",
    legalcomp_pbd_principle_usercentric: "<strong style=\"color:var(--white);\">Gebruikersgericht:</strong> Betrokkenen staan centraal bij alle beslissingen",
    legalcomp_sbd_heading: "Security by Design (SbD)",
