    legalcomp_rai_section_label: "Verantwoorde AI",
    legalcomp_rai_section_title: "Onze Verbintenis tot Verantwoorde AI",
    legalcomp_rai_section_desc: "Blue Bridge zet zich in voor AI die organisaties ten goede komt met respect voor individuele rechten en maatschappelijke waarden.",
    legalcomp_rai_card_transparency_title: "Transparantie",
    legalcomp_rai_card_transparency_desc: "Wij maken altijd kenbaar wanneer gebruikers met AI interageren. Onze AI-systemen misleiden gebruikers niet over hun AI-aard.",
    legalcomp_rai_card_fairness_title: "Eerlijkheid",
    legalcomp_rai_card_fairness_desc: "Wij beoordelen AI-uitkomsten op vertekening en nemen corrigerende maatregelen. AI-beslissingen kunnen door mensen worden herzien en overruled.",
    legalcomp_rai_card_oversight_title: "Menselijk Toezicht",
    legalcomp_rai_card_oversight_desc: "Alle AI-systemen beschikken over duidelijke escalatiepaden naar menselijke medewerkers. Er worden geen volledig autonome AI-beslissingen genomen in domeinen met hoge inzet zonder menselijke toetsing.",
    legalcomp_rai_card_privacy_title: "Privacy",
    legalcomp_rai_card_privacy_desc: "AI-systemen zijn ontworpen met gegevensminimalisatie. Wij gebruiken geen klantgegevens om onze basismodellen te trainen zonder uitdrukkelijke toestemming.",
    legalcomp_rai_card_noprohibited_title: "Geen Verboden Toepassingen",
    legalcomp_rai_card_noprohibited_desc: "Wij ontwikkelen geen AI voor massasurveillance, biometrische identificatie zonder toestemming, sociale kredietscore, of psychologische manipulatie.",
    legalcomp_rai_card_accountability_title: "Verantwoordingsplicht",
