/* Each entry lists every hostname that IS that language's home domain. Visiting
   one of these hosts always opens in that language, regardless of any earlier
   localStorage preference — bluebridge.es is always Spanish, bluebridgeglobal.be
   is always Dutch. Picking a different language in the switcher for one of
   these two languages navigates to its home domain (see i18n.select below);
   the other languages (en/fr/pt/de) have no dedicated domain, so they just
   swap content in place on whichever domain you're already on. */
const BB_HOME_DOMAINS = {
  es: ['bluebridge.es', 'www.bluebridge.es'],
  nl: ['bluebridgeglobal.be', 'www.bluebridgeglobal.be'],
};

/* ── i18n Engine ── */
const i18n = {
  current: 'en',
  langs: { en: '🇺🇸 EN', es: '🇪🇸 ES', fr: '🇫🇷 FR', nl: '🇳🇱 NL', pt: '🇧🇷 PT', de: '🇩🇪 DE' },

  hostDefaultLang() {
    const host = (typeof location !== 'undefined' ? location.hostname : '').toLowerCase();
    for (const lang of Object.keys(BB_HOME_DOMAINS)) {
      if (BB_HOME_DOMAINS[lang].includes(host)) return lang;
    }
    return null;
  },

  init() {
    const hostDefault = this.hostDefaultLang();
    const saved = localStorage.getItem('bb_lang');
    const browser = navigator.language?.slice(0,2).toLowerCase();
    // Host default wins even over a saved preference: bluebridge.es must always
    // open in Spanish and bluebridgeglobal.be must always open in Dutch, so
    // that invariant can't be defeated by a language picked on a past visit to
    // the other domain. Only domains with no fixed language (none today) fall
    // back to the saved/browser/en chain.
    const lang = hostDefault || saved || (BB_TRANSLATIONS[browser] ? browser : 'en');
    this.set(lang, false);
  },

  set(lang, save = true) {
    if (!BB_TRANSLATIONS[lang]) lang = 'en';
    this.current = lang;
    if (save) localStorage.setItem('bb_lang', lang);
    document.documentElement.lang = lang;
    this.apply();
    this.updateSwitcher();
  },

  /* Called from the language-switcher UI (never from init/set directly). For
     es/nl this may navigate to that language's home domain instead of just
     swapping content in place, keeping the current page path so "Pricing" on
     bluebridgeglobal.be jumps to the same Pricing page on bluebridge.es. For
     every other language (or when already on the right domain) it behaves
     exactly like set(). */
  select(lang) {
    const homeHosts = BB_HOME_DOMAINS[lang];
    const currentHost = location.hostname.toLowerCase();
    if (homeHosts && !homeHosts.includes(currentHost)) {
      localStorage.setItem('bb_lang', lang);
      location.href = 'https://' + homeHosts[homeHosts.length - 1] + location.pathname + location.search + location.hash;
      return;
    }
    this.set(lang);
  },

  t(key) {
    return BB_TRANSLATIONS[this.current]?.[key] || BB_TRANSLATIONS.en?.[key] || key;
  },

  apply() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.dataset.i18n;
      const val = this.t(key);
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
        el.placeholder = val;
      } else {
        el.textContent = val;
      }
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      el.innerHTML = this.t(el.dataset.i18nHtml);
    });
  },

  updateSwitcher() {
    document.querySelectorAll('.lang-current').forEach(el => {
      el.textContent = this.current.toUpperCase();
    });
    document.querySelectorAll('.lang-menu a').forEach(a => {
      a.classList.toggle('active', a.dataset.lang === this.current);
    });
  }
};
